def P(n):
    return n**3 + 3*n**2 - 13*n - 15

test_values = [1, 3, 5, 15]
roots = []
for n in test_values:
    if P(n) == 0:
        roots.append(n)
    print(f"P({n}) = {P(n)}")

print(f"Positive integer roots found: {roots}")

def f(n):
    return n**3 + 3*n**2 - 13*n - 15

roots = []
for n in range(1, 11):
    if f(n) == 0:
        roots.append(n)

print(f"Roots found for n up to 10: {roots}")
